input.code:
const tab = await tools.browser.tabs.open('https://www.youtube.com/watch?v=VqEbCxg2bNI', {focus: false});
await new Promise(r => setTimeout(r, 4000));
const res = await tools.browser.evaluate({
  tabID: tab.id,
  script: `(() => {
    try {
      const pr = window.ytInitialPlayerResponse || null;
      if (!pr) return {ok:false, reason:'no ytInitialPlayerResponse'};
      const ps = pr.playabilityStatus || {};
      const sb = pr.storyboards && pr.storyboards.playerStoryboardSpecRenderer ? pr.storyboards.playerStoryboardSpecRenderer.spec : '';
      const vd = pr.videoDetails || {};
      return {ok:true, status: ps.status, reason: ps.reason||'', spec: sb, len: vd.lengthSeconds, title: vd.title};
    } catch(e) { return {ok:false, reason:String(e)}; }
  })()`
});
return {tabID: tab.id, url: tab.url, res};

